PREFIX dbo: <http://dbpedia.org/ontology/>

SELECT ?film ?director ?birthDate
WHERE {
  VALUES ?film { 
    <http://dbpedia.org/resource/Mutiny_(1952_film)> 
    <http://dbpedia.org/resource/The_Eagle's_Feather>
  }
  ?film dbo:director ?director .
  ?director dbo:birthDate ?birthDate .
}
ORDER BY ?birthDate
LIMIT 100

